changeSet.sql:
ALTER TABLE vermietung_abrechnung ADD COLUMN abrechnungs_jahr INTEGER;
ALTER TABLE vermietung_abrechnung ADD CONSTRAINT ck_abrechnungs_jahr CHECK(abrechnungs_jahr BETWEEN 1900 AND 2998);
ALTER TABLE vermietung_abrechnung DROP CONSTRAINT vermietung_abrechnung_buchung_id_revision_key;
CREATE UNIQUE INDEX uq_abrechnung_abschluss ON vermietung_abrechnung(buchung_id,revision) WHERE abrechnungs_jahr IS NULL;
CREATE UNIQUE INDEX uq_abrechnung_jahr ON vermietung_abrechnung(buchung_id,abrechnungs_jahr) WHERE abrechnungs_jahr IS NOT NULL;
